"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[15069],{67183:e=>{e.exports=JSON.parse('{"tag":{"label":"gdpr","permalink":"/tags/gdpr","allTagsPath":"/tags","count":35,"items":[{"id":"compliance/omnibus/ai-act-amendments","title":"AI Act Amendments in the Digital Omnibus","description":"How the Digital Omnibus simplifies AI compliance and clarifies GDPR-AI intersection","permalink":"/compliance/omnibus/ai-act-amendments"},{"id":"compliance/cnil-self-assessment","title":"CNIL Self-Assessment: Sealmetrics Compliance","description":"Official CNIL self-assessment documentation for Sealmetrics analytics - demonstrating compliance with French consent exemption requirements.","permalink":"/compliance/cnil-self-assessment"},{"id":"guides/complete-guide-cookieless-analytics","title":"Complete Guide to Cookieless Analytics 2026","description":"Cookieless analytics captures 100% of visitor data without consent banners: how it works, why cookie-based tools lose 15-60% of EU data, and how to set it up.","permalink":"/guides/complete-guide-cookieless-analytics"},{"id":"compliance/compliance-overview/index","title":"Compliance Overview","description":"How Sealmetrics meets GDPR, ePrivacy, and CNIL requirements: bot filtering, legal analysis, and a legal FAQ for consentless, cookieless analytics.","permalink":"/compliance/compliance-overview/"},{"id":"faq/consentless-analytics","title":"Consentless Analytics","description":"Why Sealmetrics needs no consent banner \u2014 no cookies, no fingerprinting, no personal data, and what exactly is recorded on each hit.","permalink":"/faq/consentless-analytics"},{"id":"security-privacy/data-location","title":"Data Location & Retention","description":"Where Sealmetrics stores your data and how long it\'s retained. EU-based infrastructure with clear retention policies.","permalink":"/security-privacy/data-location"},{"id":"compliance/data-subject-rights","title":"Data Subject Rights (DSAR)","description":"How data subject access requests work with Sealmetrics \u2014 why visitor requests cannot be linked to any record, and how account-holder rights are handled.","permalink":"/compliance/data-subject-rights"},{"id":"compliance/GDPR-and-ePrivacy/do-session-ids-require-consent","title":"Do Temporary Session Identifiers (Session IDs) Require Consent Under GDPR?","description":"When a session ID triggers the ePrivacy consent requirement and when it does not, and why Sealmetrics\' short-lived, context-derived marker falls on the no-consent side.","permalink":"/legal/gdpr-and-eprivacy/do-session-ids-require-consent"},{"id":"compliance/omnibus/edpb-edps-opinion","title":"EDPB-EDPS Joint Opinion on the Digital Omnibus","description":"Official position of European data protection authorities on the Digital Omnibus proposal - concerns, support, and recommendations","permalink":"/compliance/omnibus/edpb-edps-opinion"},{"id":"compliance/omnibus/index","title":"EU Digital Omnibus Regulation","description":"Complete guide to the EU Digital Omnibus Regulation (COM(2025) 837) simplifying GDPR, ePrivacy, and data legislation","permalink":"/compliance/omnibus/"},{"id":"compliance/omnibus/gdpr-changes","title":"GDPR Amendments in the Digital Omnibus","description":"Detailed analysis of GDPR changes: personal data definition, pseudonymization, AI training, breach notifications","permalink":"/compliance/omnibus/gdpr-changes"},{"id":"compliance/gdpr-cookieless-analytics","title":"GDPR and Cookieless Analytics","description":"How cookieless analytics comply with GDPR requirements and provide better data without consent banners","permalink":"/compliance/gdpr-cookieless-analytics"},{"id":"compliance/GDPR-and-ePrivacy/index","title":"GDPR and ePrivacy","description":"Why a dataset with no personal data sits outside the GDPR, how the ePrivacy consent rule works, and when a session ID does or does not require consent.","permalink":"/legal/gdpr-and-eprivacy"},{"id":"security-privacy/attribution-without-userid","title":"How Attribution Works Without a User-ID","description":"How Sealmetrics attributes traffic and conversions without User-IDs, cookies or cross-session tracking \u2014 last-click attribution read from the URL on every hit.","permalink":"/security-privacy/attribution-without-userid"},{"id":"lens/seal-ai/private-ai-architecture","title":"How Seal AI Works: Private AI on European Infrastructure","description":"The architecture behind Seal AI: EU-only inference on Scaleway Paris, zero retention, no training on your data, and why no data is ever transferred to the United States.","permalink":"/lens/seal-ai/private-ai-architecture"},{"id":"compliance/compliance-overview/how-sealmetrics-blocks-bot-traffic","title":"How Sealmetrics Blocks Bot Traffic (And Stays Consentless)","description":"How Sealmetrics filters bot traffic with layered, privacy-safe defenses \u2014 and why its ephemeral, in-memory use of IPs keeps the platform GDPR and ePrivacy compliant.","permalink":"/compliance/compliance-overview/how-sealmetrics-blocks-bot-traffic"},{"id":"security-privacy/country-detection","title":"How Sealmetrics determines the country without using IP addresses","description":"How Sealmetrics detects visitor country from the browser timezone instead of IP addresses \u2014 GDPR-friendly geo data with zero personal data processing.","permalink":"/security-privacy/country-detection"},{"id":"security-privacy/how-we-protect-privacy","title":"How Sealmetrics Protects User Privacy","description":"The concrete protections behind Sealmetrics \u2014 no cookies, no persistent identifiers, no stored IP addresses, EU-only storage and short retention.","permalink":"/security-privacy/how-we-protect-privacy"},{"id":"compliance/omnibus/timeline-implementation","title":"Implementation Timeline","description":"Key dates and milestones for the EU Digital Omnibus: proposal publication, committee assignments, feedback periods, and the expected GDPR change timeline.","permalink":"/compliance/omnibus/timeline-implementation"},{"id":"compliance/compliance-overview/is-sealmetrics-privacy-compliant","title":"Is Sealmetrics GDPR, ePrivacy, CCPA, and PECR Compliant?","description":"Learn how Sealmetrics ensures full compliance with GDPR, ePrivacy, CCPA, PECR, and global privacy regulations through its privacy-first, isolated-hit architecture.","permalink":"/compliance/compliance-overview/is-sealmetrics-privacy-compliant"},{"id":"compliance/index","title":"Legal & Compliance","description":"Sealmetrics needs no consent banner because it stores no personal data. Self-assessments against CNIL, UK PECR, TDDDG, Garante and FADP criteria, plus the DPA.","permalink":"/compliance/"},{"id":"security-privacy/privacy-by-design","title":"Privacy by Design Principles","description":"How Sealmetrics maps to the seven Privacy by Design principles \u2014 with the concrete architectural choice behind each one.","permalink":"/security-privacy/privacy-by-design"},{"id":"index","title":"Sealmetrics Docs \u2014 Consentless Web Analytics","description":"Official documentation for Sealmetrics, the consentless web analytics platform that captures 100% of traffic without cookies or consent banners, fully GDPR compliant.","permalink":"/"},{"id":"compare/fathom","title":"Sealmetrics vs Fathom: EU Isolation vs EU-only storage","description":"Fathom hashes IP and user agent daily and stores anonymised data in the US after EU processing. Sealmetrics never hashes the IP and keeps all data in Dublin.","permalink":"/compare/fathom"},{"id":"compare/google-analytics-4","title":"Sealmetrics vs Google Analytics 4: consent-based vs consentless measurement","description":"GA4 needs cookies and consent, so it loses 15\u201360% of EU visitors. Sealmetrics measures every hit without cookies, IP storage or a banner, hosted in Dublin.","permalink":"/compare/google-analytics-4"},{"id":"compare/matomo","title":"Sealmetrics vs Matomo: self-hosted open source vs managed consentless cloud","description":"Matomo is GPL-licensed and self-hostable, but its cookieless mode hashes the visitor\'s IP. Sealmetrics never uses the IP and stores everything in Dublin.","permalink":"/compare/matomo"},{"id":"compare/piwik-pro","title":"Sealmetrics vs Piwik PRO: enterprise suite with consent manager vs consentless by design","description":"Piwik PRO pairs analytics with a consent manager and an anonymous mode hashed from the IP. Sealmetrics needs no consent layer, no IP and stores only in Dublin.","permalink":"/compare/piwik-pro"},{"id":"compare/plausible","title":"Sealmetrics vs Plausible: two cookieless tools, one hashes the IP","description":"Plausible identifies visitors with a daily hash of IP and user agent; Sealmetrics never derives an identifier from the IP. Both cookieless, both EU-hosted.","permalink":"/compare/plausible"},{"id":"compare/simple-analytics","title":"Sealmetrics vs Simple Analytics: the closest architecture, different depth","description":"Both skip cookies, IPs and consent banners and derive country from the timezone. Simple Analytics keeps it minimal; Sealmetrics adds attribution, e-commerce and AI.","permalink":"/compare/simple-analytics"},{"id":"security-privacy/index","title":"Security & Privacy","description":"How Sealmetrics measures without personal data \u2014 four non-identifying variables, nothing on the device, EU-only storage in Dublin \u2014 with the index of every privacy and security page.","permalink":"/security-privacy/"},{"id":"compliance/omnibus/smes-small-midcaps","title":"SME and Small Mid-Cap Exemptions","description":"How the Digital Omnibus extends small business protections to companies with up to 749 employees","permalink":"/compliance/omnibus/smes-small-midcaps"},{"id":"compliance/subprocessors","title":"Subprocessors","description":"Sealmetrics subprocessors are listed in Annex 3 of the DPA at sealmetrics.com/dpa \u2014 the authoritative list; change notifications by email on request.","permalink":"/compliance/subprocessors"},{"id":"faq/privacy-technical","title":"Technical Privacy Model","description":"Learn exactly what data Sealmetrics collects, what it does not collect, and how privacy is enforced technically.","permalink":"/faq/privacy-technical"},{"id":"security-privacy/consentless-analytics","title":"What is Consentless Analytics?","description":"What consentless analytics is, the four non-identifying variables Sealmetrics records, and why measuring without personal data means no consent banner is required.","permalink":"/security-privacy/consentless-analytics"},{"id":"security-privacy/why-no-consent","title":"Why Sealmetrics Can Measure Without Consent","description":"Sealmetrics needs no consent banner because it collects no personal data and stores nothing on the visitor\'s device \u2014 the short version of the legal basis.","permalink":"/security-privacy/why-no-consent"}],"unlisted":false}}')}}]);